  "江苏|新沂市圣泉湖景区": "圣泉湖在新沂，湖面由水库蓄水而成，四周是低缓的丘陵与农田。湖岸有垂钓点与农家乐，水质清，夏季可划船，环湖道路不长，是新沂人周末就近活动的去处。",
  "江苏|徐州市丰县程子书院": "徐州市丰县程子书院位于徐州，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
