  "江苏|徐州铜山区渡江战役总前委旧址": "渡江战役总前委旧址在徐州铜山区汉王镇北望村，一九四九年邓小平、陈毅等在此指挥渡江战役的准备工作。旧址为石墙瓦房，室内按原样陈设桌椅与地图，院落简朴。",
  "江苏|徐州欧乐堡海洋极地世界": "欧乐堡海洋极地世界在徐州，馆内分海洋与极地两片展区，白鲸、企鹅与海豚是主要展示对象。海底隧道与水母展缸适合拍照，表演场按场次开放，多为家庭游客的半日行程。",
  "江苏|沛县博物馆": "沛县博物馆位于徐州，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|徐州九顶山动物园": "徐州九顶山动物园位于徐州，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|邳州大运河红枫森林景区": "大运河红枫森林在邳州，运河滩地上种着成片红枫与彩叶树种，深秋叶色转红。林间步道与观景平台沿河布置，秋季是最热闹的时候，其余季节以林下花田和露营为主。",
  "江苏|徐州邳州市小萝卜头纪念馆": "徐州邳州市小萝卜头纪念馆位于徐州，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|丰县润丰湖景区": "润丰湖在丰县，是城郊的水库型湖面，岸线平缓，四周为果林与农田。湖边设步道与亲水平台，垂钓与骑行的人较多，是丰县城区附近少有的开阔水面。",
  "江苏|丰县县委旧址（张后屯）景区": "丰县县委旧址在丰县张后屯村，是抗日战争时期中共丰县县委的活动地。院落为当地民居样式，展室陈列文件、油印机与旧照片，村道与老屋保持原貌，是丰县红色教育的一处基点。",
  "江苏|睢宁古黄河路亚景区": "古黄河路亚景区在睢宁，沿黄河故道的河道开展路亚垂钓，水面狭长，岸边设钓位与木平台。景区以钓鱼赛事和体验为主，配套露营与烧烤，是苏北少见的以路亚为主题的休闲地。",
