  "江苏|常州武进宋剑湖生态旅游区": "宋剑湖在常州武进区遥观镇，湖面由低洼圩区整理而成，环湖有绿道与湿地岛。湖区保留部分芦苇与荷塘，白鹭常见，周边是工业镇区，因此成为当地难得的开放水面。",
