  "江苏|常州市江南环球港": "江南环球港在常州新北区，是一座大型商业综合体，室内有摩天轮、影院与滑冰场。建筑以欧式穹顶和长廊装饰，餐饮与零售集中，夜间灯光亮眼，属城市商业空间的旅游化尝试。",
  "江苏|常州三杰纪念馆": "常州三杰纪念馆位于常州，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|常州革命烈士纪念地": "常州革命烈士纪念地在市区，园内立烈士纪念碑与名录墙，纪念馆陈列常州籍烈士的事迹与遗物。松柏围绕，环境肃静，清明前后祭扫的人多，是常州开展纪念活动的主要场所。",
  "江苏|曹山美音茶园": "曹山美音茶园位于常州，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|别桥原乡旅游区": "别桥原乡在溧阳别桥镇，村落、稻田与河塘连成一片，老屋改成民宿与展馆。景区以原乡生活为主题，设农事体验与手作课程，溧阳1号公路从附近经过，适合住一晚慢慢逛。",
  "江苏|茅山金牛洞景区": "金牛洞在金坛茅山，是山间的一处溶洞，洞道不长，钟乳石与石笋发育一般，却保留着道教洞天福地的说法。洞外山林清幽，与茅山其他景点以山路相连，游客较少。",
  "江苏|江苏西太湖影视产业基地": "西太湖影视产业基地在常州武进区，建有民国街、老上海场景与摄影棚，多部年代剧在此拍摄。基地开放部分街区供参观，可看布景、道具与服装，偶遇剧组时需绕行。",
  "江苏|神马农场": "神马农场在溧阳戴埠镇竹海大道旁，占地不大，设马术体验、花田、果园与萌宠区。山道滑车是较受欢迎的项目，周边即南山竹海与温泉，多作为亲子行程中的一站。",
  "江苏|嬉乐湾景区": "嬉乐湾在常州武进区礼嘉镇，是一处生态农业示范园，温室里种着热带水果与花卉，室外有草坪和水上项目。园区以亲子游乐与农事体验为主，规模较大，节假日活动较多。",
  "江苏|姜下鹅湖公园": "姜下鹅湖公园位于常州，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|庆丰一方味稻景区": "庆丰一方味稻在溧阳南渡镇庆丰村，以连片稻田为核心，田埂上设观景台与艺术装置。村里把旧房改成咖啡馆、面馆与展馆，稻米是主要物产，秋季收割前后景色最好。",
