  "江苏|南通市军山景区": "军山在南通五山中最东，临江而立，山上有普陀别院与观音像。山体由火山岩构成，林间栈道可上至望江台，与狼山、剑山隔水相望，游人比狼山少，适合安静地走一段山路。",
  "江苏|南通市城市绿谷": "南通市城市绿谷位于南通，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|南通启东市黄金海滩景区": "黄金海滩在启东圆陀角，长江入海口北侧的滩涂，沙质细软，退潮后露出大片湿地。这里可观日出与江海交汇，风筝与沙滩车是常见项目，附近立着长江入海口的标志碑。",
