  "江苏|南通如皋市中华长寿文化谷": "中华长寿文化谷在如皋，依托当地长寿之乡的名声，园区讲养生、膳食与寿星故事。展馆陈列百岁老人的资料，园内多种药食两用植物，与如皋盆景、早茶习俗相互呼应。",
  "江苏|南通如皋市龙游湖风景区": "龙游湖在如皋城南，湖面由取土区蓄水形成，环湖绿道与草坪开阔。湖边有沙滩、儿童游乐与露营区，傍晚散步的人多，是如皋新城区最主要的一处开放水面。",
  "江苏|南通启东市番茄俱乐部": "番茄俱乐部在启东，以番茄种植与加工为主题，温室内可看无土栽培与品种对比。园区设采摘、番茄制品品尝与亲子课堂，规模不大，多为周边家庭在周末前来。",
