  "江苏|唐闸北市景区": "唐闸北市在南通崇川区唐闸镇，清末张謇在此创办大生纱厂，形成工人居住与商业街区。钟楼、厂房与堆栈保留下来，红砖建筑沿河排列，是近代民族工业城镇的完整样本。",
  "江苏|青青牧场景区": "青青牧场在南通近郊，以奶牛养殖与乳品体验为主题，设挤奶演示、草料区和手工课堂。场地以草地为主，适合低龄儿童，活动按场次安排，多为半日游的亲子去处。",
  "江苏|通州开沙岛房车露营地景区": "开沙岛在南通通州区长江中，房车露营地沿江堤布置，提供房车位、木屋与帐篷。岛上多林地与农田，可骑行、烧烤和看江轮，需乘渡船或经大桥上岛，适合过夜的短途度假。",
  "江苏|海门通东革命老区红色记忆馆": "海门通东革命老区红色记忆馆位于南通，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|海门九龙岛文化湿地景区": "九龙岛文化湿地在海门，水面与芦苇荡间分布小岛，木栈道与拱桥相连。景区以湿地观光和民俗展示为主，设有农耕器具陈列，周边是海门的乡村与农田，环境安静。",
  "江苏|南通启东市梦幻长岛景区": "梦幻长岛在启东长江口，是一处沙洲型的江岛，岛上林地、滩涂与农庄相间。景区有露营、垂钓与亲子项目，需乘船往返，江风大，适合天气晴好的日子短途游玩。",
  "江苏|启东农道有机公园景区": "启东农道有机公园景区位于南通，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|启东印象沙地景区": "印象沙地在启东，以沙地文化为主题，园区用沙雕、草屋与农具展示江海滩涂上的垦殖生活。启东多沙土，棉花与四青作物曾靠沙地生长，景区把这些记忆做成可看的场景。",
  "江苏|李昌钰刑侦科学博物馆": "李昌钰刑侦科学博物馆位于南通，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
