  "江苏|通州鲜花小镇景区": "通州鲜花小镇在南通通州区，花田随季节换种郁金香、马鞭草与菊花，另设花艺教室与集市。园区以拍照和亲子活动为主，春秋花季人气较旺，周边是通州的乡村河道。",
