  "江苏|南通市龙信文化旅游景区": "龙信文化旅游景区在海门，由本地建筑企业建设，园区展示建筑施工工艺与鲁班文化。设有工法样板、木作体验与展馆，能看装配式建筑的构件，属企业办的工业参观类景区。",
  "江苏|南通市洲际梦幻岛景区": "洲际梦幻岛在通州区，与洲际绿博园相邻，园区以亲子游乐为主题，设无动力设施、萌宠乐园与戏水区。场地开阔，演出与活动按节假日安排，多为南通市区家庭的一日游选择。",
  "江苏|连云港灌南县人民革命纪念馆": "连云港灌南县人民革命纪念馆位于连云港，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
