  "江苏|连云港赣榆区海州湾旅游度假区": "海州湾度假区在连云港赣榆区，海岸线平直，沙滩与浅海适合戏水。区内有海鲜餐饮与民宿，夏季游人集中，附近的海州湾国家级海洋公园以沙质海岸与潮间带生物为保护对象。",
  "江苏|连云港市宿城船山飞瀑景区": "连云港市宿城船山飞瀑景区位于连云港，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|连云港赣榆区徐福泊船山景区": "徐福泊船山在赣榆金山镇，相传秦代徐福东渡前曾在此泊船。山上有徐福祠与塑像，展室讲徐福入海的传说与中日文化交流，山下的海岸与渔村是背景，海拔不高，步行可达。",
  "江苏|连云港市云龙涧原生态景区": "云龙涧在连云港云台山北麓，山谷中有溪流与多处跌水，雨后水量较大。涧边修有石阶与观景台，林木茂密，夏季凉爽，冬季则见冰瀑，是本地人周末走山的一条短线。",
  "江苏|连云港灌云县烈士陵园": "连云港灌云县烈士陵园位于连云港，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|连云港赣榆区和安湖湿地公园景区": "连云港赣榆区和安湖湿地公园景区位于连云港，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
