  "江苏|连云港市海州湾海洋乐园": "连云港市海州湾海洋乐园位于连云港，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|连云港市夹谷圣境景区": "夹谷圣境在赣榆，依托夹谷山的齐鲁会盟传说，山间建有书院、圣殿与石刻。相传孔子相鲁时随鲁定公与齐侯会于夹谷，景区据此立像设展，山道与林地在其周围展开。",
  "江苏|连云港市孔雀沟景区": "孔雀沟在连云港云台山，山谷狭长，溪水与巨石交错，林木遮蔽。沟内步道沿溪上行，夏季可涉水，相传旧时多孔雀栖息，山下与花果山景区相距不远，游客相对少些。",
  "江苏|连云港赣榆区抗日山景区": "抗日山在赣榆西部，山上建有烈士陵园与纪念塔，安葬着抗战时期牺牲的八路军将士。石阶自山脚通向塔前，墓碑成排，陵园内的纪念馆陈列战役史料，是苏北重要的抗战纪念地。",
  "江苏|连云港市灌云梅园景区": "连云港市灌云梅园景区位于连云港，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|连云港市灌云县开山岛": "开山岛在灌云以东的黄海海面，面积很小，岛上有哨所、灯塔与几间营房。王继才夫妇在此守岛三十二年，事迹广为人知，登岛需乘船，风浪大时难以上岸，岛上无常住居民。",
  "江苏|连云港市连云区凰窝景区": "凰窝在连云区，是一处临海的山湾，礁石与沙滩相间，山坡多松林。这里以海边露营和看日出为主，设施简单，游人少，适合避开热闹海滨的清净行程。",
  "江苏|羊山岛景区": "羊山岛在连云港连云区近岸，岛上礁石嶙峋，海蚀柱与潮间带生物是主要看点。环岛步道不长，可看渔船与港口，退潮时能走到岩滩，是本地人赶海与拍照的一处小岛。",
  "江苏|都市四季果园": "都市四季果园位于连云港，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
