  "江苏|淮安市苏皖边区政府旧址纪念馆": "淮安市苏皖边区政府旧址纪念馆位于淮安，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|淮安市周恩来童年读书处": "周恩来童年读书处在清江浦，是周恩来幼年随家迁居淮安后读书的宅院。青砖小院里有书房与厅堂，陈列着书桌、油灯与家书，附近即里运河的码头，环境朴素安静。",
  "江苏|淮安市钵池山景区": "钵池山在清江浦区，原是道教七十二福地之一，山体早被采石削平，今为城市公园。园内有山阳公祠、老子像与湖面，传说王子乔在此炼丹，地名沿用千年，是城内少见的道教遗迹。",
  "江苏|淮安市韩信故里景区": "淮安市韩信故里景区位于淮安，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
