  "江苏|苏北小延安景区": "苏北小延安在涟水县成集镇，抗战时期这一带是淮海区党政机关的驻地，被称为苏北小延安。旧址群含办公用房与地道，展陈讲根据地建设，村庄仍以农业为主，环境安静。",
  "江苏|金鸡坨生态景区": "金鸡坨在涟水县红窑镇夏楼村，紧邻盐河，是一处生态农庄。园区有荷塘、果园、土灶与民宿，另设民俗馆与拓展区，以农耕体验和亲子活动为主，周边是涟水的平原农田。",
