  "江苏|沈坤状元府": "沈坤状元府坐落在淮安区河下，沈坤是明代淮安籍状元，曾组织乡兵抗倭。宅院按明代官宦府第复原，设书房、厅堂与展室，讲其科举经历与抗倭事迹，与吴承恩故居同在一条街上。",
