  "江苏|大丰狮子口会师文化景区": "狮子口会师文化景区在大丰白驹镇，一九四〇年八路军第五纵队与新四军在此会师。景区立会师纪念碑与群雕，展馆讲华中抗日力量的整合，周边是白驹的田野与河网，环境开阔。",
  "江苏|七彩阜宁农业公园景区": "七彩阜宁农业公园景区位于盐城，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|陆秀夫纪念馆景区": "陆秀夫纪念馆景区位于盐城，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|梨花语景区": "梨花语景区在滨海县，以万亩生态梨园为核心，春季梨花连片开放。园内设梨园步道、印象梨花坞与萌宠区，秋季可采摘，村庄的民居与梨树相间，是盐城北部农业观光的典型村落。",
  "江苏|射阳淮海军垦纪念馆景区": "射阳淮海军垦纪念馆景区位于盐城，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|射阳鹤乡菊海景区": "鹤乡菊海在射阳洋马镇，当地种药菊的历史较长，秋季成片菊花开放。园区设观赏品种区与加工展示，可看菊花烘制与药材分拣，花期集中在十月前后，周边是射阳的平原农田。",
  "江苏|黄尖牡丹园": "黄尖牡丹园位于盐城，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|杨侍生态园": "杨侍生态园位于盐城，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|月亮湾景区": "月亮湾在盐城滨海县滨海港片区，东临黄海，北接翻身河，古黄河在此入海。景区以沙滩、亲水步道与黄河记忆为主题，海堤外是滩涂与浅海，日出与潮水是主要看点，附近有风电与盐田。",
  "江苏|荷花漫景区": "荷花漫在建湖县，以千亩荷田为主体，木栈道穿行花间。景区结合捕鱼体验、荷膳与红色教育点，夏季花期最盛，莲子与藕制品在门口售卖，是建湖水乡的农旅项目。",
  "江苏|泊心黄沙港": "泊心黄沙港在射阳黄沙港镇，是一处渔港风情街区，码头停着渔船，岸上设海鲜市场与民宿。开渔季节鱼市热闹，可看卸货与分拣，海堤外的滩涂与风车构成背景。",
