  "江苏|扬州市吴道台宅第": "吴道台宅第在扬州老城，清末宁绍道台吴引孙所建，宅院融合扬州民居与西洋元素。侧园的测海楼是著名藏书楼，曾藏书上万卷，砖雕门楼与九十九间半的院落保存较好。",
