  "江苏|扬州荷花池景区": "荷花池景区在扬州城区，原为清代盐商的私家园林，池中植荷，岸边叠石与亭榭相间。园子不大，夏季荷花开放时最可观，附近的老街与菜场让这里仍带着居民区的气息。",
  "江苏|扬州宝应县荷园生态旅游区": "扬州宝应县荷园生态旅游区位于扬州，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|扬州高邮市清水潭景区": "清水潭在高邮，是运河与湖荡之间的一处湿地，水面清浅，芦苇与林木环绕。景区设栈道与观鸟点，盛夏荷开，深秋芦白，周边以水产养殖和农田为主，游人不多。",
  "江苏|勇龙国际生态园": "勇龙国际生态园位于扬州，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|郭村保卫战纪念馆": "郭村保卫战纪念馆位于扬州，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|扬州梦幻之城景区": "扬州梦幻之城景区位于扬州，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|“江上盐都”历史文化旅游区": "江上盐都在仪征十二圩，清末民初这里是淮盐出江的转运中心，盐栈与码头沿江排开。街区复原了盐号、会馆与仓房，展陈讲盐票、船帮与运河转运，江堤外仍见船影。",
  "江苏|北湖湿地旅游景区": "北湖湿地在扬州邗江区，邵伯湖西侧的湖滩与鱼塘经整理成为湿地公园。水网、苇丛与林地交错，设栈道与观鸟屋，游客以本地骑行和露营为主，尚未完全商业化。",
  "江苏|龙山森林公园景区": "龙山森林公园景区位于扬州，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|红山体育度假乐园景区": "红山体育度假乐园景区位于扬州，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|珠湖小圳景区": "珠湖小圳在高邮，紧邻高邮湖，村落沿河渠展开，水圳与田埂把村庄切成小块。景区以水乡田园和民宿为主，可垂钓、采摘与骑行，规模不大，属高邮湖畔的乡村旅游点。",
  "江苏|镇江市江苏禾木农博园": "镇江市江苏禾木农博园位于镇江，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
