  "江苏|镇江市扬中宜禾职业装博览馆": "镇江市扬中宜禾职业装博览馆位于镇江，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|镇江句容市怡景湾度假村景区": "镇江句容市怡景湾度假村景区位于镇江，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|镇江市新区城市中央公园": "镇江市新区城市中央公园位于镇江，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|镇江市江心洲橘江里景区": "橘江里在镇江丹徒区的江心洲，长江中的沙洲上种着柑橘与蔬菜。景区以江岛田园为主题，设采摘、露营与江堤步道，需乘汽渡上岛，秋季橘子成熟时游客较多。",
  "江苏|镇江扬中市园博园": "镇江扬中市园博园位于镇江，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|镇江句容市伏热花海景区": "伏热花海在句容白兔镇，坡地上种着薰衣草、马鞭草与向日葵，花期按季节轮换。园区设风车、教堂式小品与花艺市集，多为拍照与亲子游客，附近有草莓采摘园。",
  "江苏|镇江句容市茅山半岛景区": "茅山半岛在句容茅山景区外围，依托水库与山谷地形，布置度假酒店、草坪与环湖步道。这里以住宿和会议为主，可远望茅山山脊，与九霄万福宫等道教景点分处山南山北。",
  "江苏|镇江丹阳市九里风景区": "九里风景区在丹阳延陵镇，季子庙供奉春秋吴国公子季札，庙前九里沸泉分为数池，水味各异。庙内有十字碑与历代碑刻，季札挂剑的故事在此流传，是丹阳最重要的古迹之一。",
  "江苏|镇江丹徒开心休博园": "镇江丹徒开心休博园位于镇江，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|香海琴枫景区": "香海琴枫在丹阳，园区以花卉、果园与草坪为主，设有婚庆场地和亲子游乐区。以三国人物孙尚香为线索布置演艺与互动，另有花田和小火车，属苏南的农旅结合项目。",
  "江苏|泰州市引江河风景区": "引江河风景区在泰州，沿引江河两岸展开，河道为南水北调与区域供水的水利工程。河堤绿化成带，设闸站参观与滨河步道，水面宽阔，可看江都水利枢纽体系的运作。",
  "江苏|泰州市中国人民解放军海军诞生地纪念馆": "泰州市中国人民解放军海军诞生地纪念馆位于泰州，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|泰州靖江市牧城景区": "泰州靖江市牧城景区位于泰州，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|泰州泰兴市国家古银杏公园": "泰州泰兴市国家古银杏公园位于泰州，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|泰州市麒麟湾景区": "麒麟湾在泰州城郊，以生态农业和亲子游乐为主，园区有花田、果园、萌宠与水上项目。场地临河，绿地开阔，节假日活动较多，是泰州城区周边常见的短途休闲去处。",
  "江苏|泰州兴化市施耐庵文化园": "泰州兴化市施耐庵文化园位于泰州，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|泰州泰兴市黄桥小南湖风景区": "小南湖在泰兴黄桥镇，湖面由取土坑蓄水形成，环湖有步道、亭桥与草坪。景区与黄桥镇区的战役纪念馆相距不远，可安排在同一条线路上，傍晚本地人来此散步。",
  "江苏|泰州兴化市乌巾荡湿地公园": "泰州兴化市乌巾荡湿地公园位于泰州，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|泰州白马文化旅游区": "白马文化旅游区在泰州高港区白马镇，一九四九年人民海军在此宣告成立，镇上有海军诞生地纪念馆。园区陈列舰艇模型、军服与史料，白马庙旧址与庙会民俗也在其中。",
  "江苏|泰州兴化市金东门老街景区": "泰州兴化市金东门老街景区位于泰州，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的江南乡土气息与地域特色。",
  "江苏|泰州市本草养生景区": "本草养生景区在泰州，以中医药文化为主题，园内种植药草并设展馆讲药材炮制。可看切片、称量与膏方制作，另设养生餐饮与体验课程，是医药企业参与建设的参观类园区。",
  "江苏|泰兴市马甸水利枢纽风景区": "马甸水利枢纽在泰兴，是引江河与如泰运河交汇处的水利工程，节制闸与泵站并列。景区开放部分闸区供参观，可看船闸过船与泵站机组，河堤绿化成带，属工程参观型景点。",
  "江苏|兴化市万亩荷塘景区": "万亩荷塘在兴化，连片荷田沿河荡铺开，夏季荷花与莲蓬是主角。景区设木栈道、观荷台与采莲船，周边村庄以荷藕和水产为业，是里下河地区规模较大的荷田景观。",
  "江苏|泰州市香草湾景区": "香草湾在泰州，园区种着薰衣草、迷迭香与薄荷等香草，设精油手作与花田拍照区。规模不大，花期集中在春末夏初，多与亲子研学结合，是城郊的香草主题农园。",
  "江苏|泰州市凤栖湖景区": "凤栖湖在泰州，湖面开阔，环湖绿地与步道围绕，湖中设岛与桥。周边为新城住宅与学校，傍晚跑步与放风筝的人多，是城东居民常去的开放水域。",
