  "江苏|兴化市大纵湖景区": "兴化大纵湖在兴化西北，与盐城大纵湖同属一湖，湖中芦苇荡与垛田交错。景区以荷塘、水巷与渔村为主，可乘船穿行芦荡，深秋芦花雪白，寒冬水鸟翔集，湖鲜以蟹与青虾出名。",
  "江苏|宿迁市印象黄河景区": "印象黄河在宿迁，沿黄河故道布置，河道与堤岸经整治成为带状公园。沿岸有雕塑、广场和骑行道，讲黄河改道与宿迁的水患记忆，是城区西侧的一条开放绿廊。",
