  "辽宁|观陵山艺术园林景区": "观陵山艺术园林景区位于铁岭，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色，适合慢慢寻访。",
