  "辽宁|昌图太阳山风景区": "太阳山风景区在昌图县，山势低缓，林草覆盖，山顶有观景台，山脚是水库与连片农田，秋收时一片金黄。",
  "辽宁|调兵山风景区": "调兵山风景区在调兵山市，山名源于金代调兵传说，山上有兀术峰与古城遗迹，山下是矿区与城区。",
  "辽宁|白鹭洲旅游度假区": "白鹭洲度假区在铁岭市，依辽河湿地建起木屋与观鸟台，春秋有白鹭等候鸟栖息，可垂钓、骑行，苇塘里水鸟多。",
  "辽宁|龙泉山城风景区": "龙泉山城风景区位于铁岭，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色，适合慢慢寻访。",
  "辽宁|开原象牙山风景区": "象牙山风景区在开原市松山镇，山形似象牙，因电视剧《乡村爱情》在此取景而走红，村里保留拍摄场景与农家院。",
