  "辽宁|朝阳县贾家店生态旅游度假区": "贾家店的生态旅游度假区铺在朝阳县丘陵间，果树与杂粮田交错，设采摘园、垂钓池和农家院，秋后办丰收节。",
  "辽宁|朝阳市天门山旅游度假中心": "天门山旅游度假中心依朝阳市郊的山谷而建，两侧石崖相对如门，林间溪流伴栈道，配套住宿与餐饮。",
  "辽宁|朝阳县盘龙山风景区": "盘龙山风景区卧在朝阳县山脊上，岩石裸露成景，山间有寺庙遗址与山泉，步道沿脊线延伸，视野开阔。",
  "辽宁|朝阳县槐树洞风景区": "槐树洞风景区藏在朝阳县一处山崖下，天然石洞旁古槐成荫，洞内有泉水，附近修有庙宇与石阶，夏季洞中清凉。",
  "辽宁|朝阳县清风岭风景区": "清风岭风景区横在朝阳县境内，沟壑纵横、林木茂密，抗战时期抗日义勇军曾在此活动，现存密营与石刻。",
  "辽宁|小平房景区": "小平房这处村落景区卧在朝阳城郊，石墙土屋保留旧貌，设村史馆、果园和农家餐，院墙上挂着老农具，可吃柴锅炖菜。",
  "辽宁|海棠河景区": "海棠河景区顺着朝阳市区河道铺开，步道与亲水平台相连，两岸栽着海棠与杨柳，春季花开，河滩可露营。",
  "辽宁|鸿博轩旅游区": "鸿博轩旅游区在朝阳市郊，以园林与展馆为主，陈列地方书画、瓷器与民俗器物，院中设水景与长廊。",
  "辽宁|花田林海景区": "花田林海景区顺着朝阳市郊的坡地铺开，油菜、向日葵与观赏草连片，周边是松林与山丘，设观景台和拍照小径。",
  "辽宁|建平喇嘛山风景区": "喇嘛山风景区立在建平县境内，山岩嶙峋，峰顶有石棚与摩崖造像，山下村落多蒙古族居民，山道陡窄。",
  "辽宁|建平天秀山旅游风景区": "天秀山旅游风景区位于建平县，山势陡起，林草覆盖，山腰散落寺庙与石阶，顶部视野开阔，山脚有溪水流过。",
  "辽宁|喀左芳草地景区": "芳草地景区在喀左县，草坡与林地相间，设蒙古包、骑马道和烤羊餐饮，夏秋有那达慕活动，草场上马群散开。",
  "辽宁|双凤山旅游景区": "双凤山旅游景区缩在朝阳市郊，两座山丘并峙如凤，山间有寺庙与果林，山脚是村落与水库，山桃春天开遍。",
