  "辽宁|河坎子景区": "河坎子景区在朝阳市，河岸台地上有果园与村落，河滩平缓，设亲水步道与农家餐，夏夜可搭帐篷，岸边柳树成行。",
  "辽宁|三家子龙轩谷旅游景区": "龙轩谷这处旅游景区藏在朝阳市郊山谷中，溪流与巨石相间，栈道缘水而上，谷口有民宿与餐厅，夜里安静。",
  "辽宁|樱琦山庄旅游度假村": "樱琦山庄旅游度假村位于朝阳，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色，适合慢慢寻访。",
  "辽宁|青龙源湿地景区": "青龙源湿地景区位于朝阳市，河汊与泡沼组成湿地，芦苇连片，是候鸟停歇地，设观鸟栈道，夏秋水势最大。",
  "辽宁|天凌野旅游景区": "天凌野旅游景区铺在朝阳市郊的山林草坡间，设露营区、篝火场地和山地步道，夜里可观星，清晨有薄雾。",
  "辽宁|月华山景区": "月华山景区卧在朝阳市郊，山形如半月，岩壁陡立，山腰有古庙遗址，山道石阶曲折而上，山脚散落几处村落。",
  "辽宁|凌源红石山生态旅游区": "红石山生态旅游区在凌源市，山体岩石呈红褐色，沟谷中有溪流与林地，步道绕行于崖下，雨后石色更红。",
  "辽宁|凌源热水汤温泉旅游度假区": "热水汤温泉度假区在凌源市，地热资源开发较早，汤池分室内外，周边是丘陵与果园，配汤屋与疗养客房。",
  "辽宁|天呈葡萄山庄旅游度假区": "天呈葡萄山庄旅游度假区位于朝阳，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色，适合慢慢寻访。",
  "辽宁|青龙山旅游景区": "青龙山旅游景区地处朝阳市，山脊起伏如龙背，松林覆盖，山间有寺庙与观景台，登临可见河谷，山门石阶很长。",
  "辽宁|大裂山生态旅游景区": "大裂山生态旅游区缩在朝阳市境内，山体被断裂切开，形成狭长裂谷与陡崖，谷底有溪流和乱石，栈道贴壁而建。",
  "辽宁|鸡冠山风景区": "鸡冠山风景区在朝阳市，峰顶岩石排列如鸡冠，山势陡峭，林间有石阶与歇脚亭，登顶可看四周山峦。",
  "辽宁|九头山景区": "九头山景区在朝阳市，九座山头连绵并立，山谷中有水库与果林，步道串起各处观景点，山间多灌木与野草。",
  "辽宁|窝铺人家生态旅游度假区": "窝铺人家度假区在朝阳市，山村保留石屋与土院，改造为民宿，游客可随农户种地、摘果、吃柴锅饭，院里晒着玉米。",
