  "湖北|牛头山国家森林公园": "牛头山国家森林公园位于十堰市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|白马山旅游区": "十堰市郊的白马山，山势舒缓，林中有古道与庙宇遗址，登顶可望城区与远山。山上的庙宇只剩墙基，林间能看到石阶。",
  "湖北|石板河旅游区": "十堰山间的河谷景点，河床由整块石板铺成，浅水漫流，两岸多树荫，夏日戏水的人多。河床的石板被水冲得光滑，浅处只没过脚踝。",
  "湖北|窑淮窑旅游区": "竹溪县窑淮镇的窑址文化景区，旧窑包与陶片散在坡地，设有制陶体验与展室。坡上散着碎陶片，窑膛的砖被烧成暗红色。",
  "湖北|竹溪县八卦山旅游景区": "竹溪县八卦山的山林与溪谷，植被茂密，步道沿山势迂回，设有观景平台。山上的林子密，路边有野生的猕猴桃。",
  "湖北|竹溪县武陵不夜城": "竹溪县武陵不夜城位于十堰市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|莲花寨风景区": "莲花寨风景区位于十堰市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|营盘山生态旅游区": "十堰境内的营盘山，山脊平缓，林木覆盖，石阶通往山顶平台。山脊上有一片平地，四周视野开阔。山风很凉。",
  "湖北|西河田园旅游区": "西河田园旅游区位于十堰市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|郧西县仙河湾旅游区": "郧西县仙河的一段河湾，水缓滩平，岸边竹林与农田相间，设有亲水步道。河湾的水面宽，岸边的竹子垂到水上。",
  "湖北|郧西县淘宝村旅游区": "郧西县淘宝村旅游区位于十堰市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
