  "湖北|郧阳区天惊洞景区": "郧阳区山中的溶洞，洞厅高阔，钟乳与石幔发育，洞内有灯光步道。洞内的石柱顶到洞顶，地面湿滑。洞口有凉气。",
  "湖北|郧阳区樱桃沟生态文化旅游区": "郧阳区的樱桃种植村，坡上樱桃成林，花期与果期游客集中，村里多农家院落。村道两旁是樱桃树，果子熟时挂满枝。",
  "湖北|郧阳烈士陵园红色旅游区": "郧阳烈士陵园红色旅游区位于十堰市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|长河湾旅游区": "十堰境内的河湾景区，水绕村舍，岸边多果木，设烧烤与露营区。河湾的沙洲上长着芦苇，水浅处能看见鱼。",
  "湖北|青峰大裂谷景区": "房县青峰镇的山地裂谷，谷壁陡直，谷底乱石与溪流并行，栈道沿裂缝深入。裂谷的石壁上有水痕，谷底少见阳光。",
  "湖北|黄花沟旅游区": "十堰山间的沟谷景点，春夏黄花铺坡，溪水从石缝流过，步道平缓。沟里的石头被水冲圆，路边有野菊。",
  "湖北|黄龙壹号生态园": "黄龙壹号生态园位于十堰市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|龙吟峡旅游景区": "十堰境内的峡谷，峡壁夹水，落差处成小瀑，栈道贴壁而行。峡中的水声在石壁间回响，栈道很窄。谷口有水潭。",
