  "湖北|元气森林咸宁工业旅游景区": "咸宁高新区的饮料工厂参观区，玻璃廊道下是灌装线，展区讲气泡水配方与水源。厂区外的绿地上立着产品展示牌。",
  "湖北|咸宁碧桂园凤凰温泉度假区": "咸宁碧桂园凤凰温泉度假区位于咸宁市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|善源谷风景区": "咸宁的善源谷，山谷中有溪流与竹林，设步道、吊桥与民宿。谷中的竹子成片，溪上有座石桥。桥下是浅溪。",
  "湖北|大泉洞风景区": "咸宁通山县的大泉洞，溶洞内暗河与石幔并存，洞口有泉涌出，可乘小船入洞。洞内的水面映着石顶，船行要低头。",
