  "湖北|黄龙山风景区": "通城县黄龙山，湘鄂赣三省交界的山场，林密谷深，山脊有古道与界碑。山脊的风大，林下多杜鹃。山道少人走。",
  "湖北|天门七屋岭旅游景区": "天门市七屋岭村的田园景区，稻田、池塘与农舍相连，设采摘与农家餐。村里的池塘养着鱼，田边有稻草堆。",
  "湖北|杨林方舟生态庄园景区": "杨林方舟生态庄园景区位于天门市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|海龙岛景区": "天门的湖岛型休闲景区，环岛步道与亲水平台相连，岛上设烧烤与儿童游乐。岛上的树以柳与杨为主，环岛路铺着碎石。",
  "湖北|胡家花园景区": "胡家花园景区位于天门市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
