  "湖北|李白村文化旅游区": "李白村文化旅游区位于孝感市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|梦南花海景区": "孝感的花海园区，花田成片，高处搭了观景台，另有儿童游乐。花田中间有座木亭，路边停着观光车。花田外是稻田。",
  "湖北|熙凤水乡旅游度假区": "孝感的水乡景区，河渠与荷塘相连，可乘船，岸边有民宿。村里的河埠头有石阶，水边泊着小船。水边有石埠。",
  "湖北|爱漫文旅小镇": "孝感的文旅小镇，街区、民宿与花田集中，节假日有市集与演出。镇上的房子刷成浅色，街角有铁艺招牌。",
  "湖北|田水湾.漫花小镇": "孝感的田园小镇，花田绕村，设亲子农场与民宿。村里的花田围着池塘，塘边有木栏。村口有停车场与游客中心。",
  "湖北|董永公园": "董永公园位于孝感市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
