  "湖北|黄香文化馆": "黄香文化馆位于孝感市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|黄龙湖马口陶文化传承基地": "汉川市马口镇的陶文化基地，龙窑与制陶作坊可参观，能亲手拉坯。基地的展室内陈列着陶罐与窑具，墙角堆着陶土。",
  "湖北|黎元洪纪念园": "黎元洪纪念园位于孝感市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|三国猇亭古战场风景区": "宜昌猇亭区的江边战场遗址，栈道沿崖临江，塑像与展板讲夷陵之战。江边的崖壁上刻着战役经过，栈道有铁索。",
  "湖北|三峡云栖谷景区": "宜昌的度假山谷，溪流与林荫步道相接，散落木屋与露营地。谷中的溪水流过石滩，路边有木栅。谷口有溪。",
  "湖北|三峡奇潭旅游区": "宜昌的溪谷景区，多级水潭与瀑布连成串，栈道贴崖而下。潭与潭之间以石阶相连，水色由浅转深。潭边有栈桥。",
  "湖北|三峡情城市休闲旅游区": "三峡情城市休闲旅游区位于宜昌市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|三峡水乡景区": "宜昌的水乡田园，河渠绕村，荷塘与稻田相间，可乘小船。村里的房子临水而建，门前有石阶下河。水里种着菱。",
  "湖北|三峡神门旅游景区": "宜昌的峡谷入口，两崖夹峙如门，溪水穿门而出，栈道沿崖上行。门内的水面平静，崖上垂下藤蔓。峡口有渡船。",
  "湖北|三峡非遗in巷景区": "宜昌的街区型景区，集中展示三峡地区非遗技艺，有手作工坊与演出。巷子里的铺面做漆器、竹编与剪纸，可旁观。",
  "湖北|三峡龙泉湖景区": "宜昌的湖库景区，水面开阔，环湖有骑行道与果园。湖边的草地开阔，傍晚有人烧烤。湖边有露营地和烧烤区。",
  "湖北|东方年华田园综合体": "东方年华田园综合体位于宜昌市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|中亚楠木林景区": "宜昌的楠木林景区，成片楠木高大，林下有溪流与栈道。林中的楠木树干通直，树下有石桌。林中有鸟叫。",
  "湖北|中武当·天柱山景区": "长阳县天柱山，山顶道观群依峰而建，石阶陡长，旧称中武当。山上的道观分几进，最上一进临着崖。山下有溪。",
