  "湖北|古潮音洞度假山寨": "古潮音洞度假山寨位于宜昌市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|同心花海景区": "枝江的花海园区，花田按季轮种，设观景塔与亲子游乐。花田边有风车与水渠，路边卖冷饮。园中有水塘。",
