  "湖北|回龙湾风景区": "宜昌的河湾景区，水绕山脚，岸边有竹林与步道。河湾的水面倒映着山影，岸边有石阶。湾里有沙洲和芦苇。",
  "湖北|嫘祖文化园景区": "嫘祖文化园景区位于宜昌市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|宜昌动物大世界": "宜昌的动物园，猛兽区、草食区与鸟园分区，另有动物表演。园中的猛兽区用壕沟隔开，鸟类区有网罩。",
  "湖北|宜昌海底世界": "宜昌的室内海洋馆，海底隧道与企鹅馆是主要展区，设有触摸池。馆内的水母缸在暗处发光，隧道里有鳐鱼。",
