  "湖北|当阳市玉泉谷生态旅游景区": "当阳玉泉山下的谷地景区，溪流与茶园相连，可串联玉泉寺游览。谷中的溪水从寺前流过，岸边有茶园。",
  "湖北|情人泉风景区": "宜昌的溶洞与地下河景区，洞内暗河可乘船，石幔垂挂。洞外的溪谷有大石与浅滩，夏天有人戏水。潭水清可见底。",
  "湖北|拈花谷旅游区": "宜昌的山谷花木景区，坡上种花，谷中有溪与木栈道。谷中的木栈道穿过花丛，尽头有凉亭。路边种着月季。",
  "湖北|枝江市枫林月季园": "枝江市枫林月季园位于宜昌市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
