  "湖北|武汉市江岸区汉口历史文化风貌区": "汉口江岸区的老街区，沿江大道上的银行、领事馆与里份建筑连片，黎黄陂路一带咖啡馆集中。里份的巷子窄，晾衣杆横在头顶。",
  "湖北|武汉市青山区张公山寨景区": "武汉市青山区张公山寨景区位于武汉市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|武汉市黄陂区木兰湖旅游度假区": "黄陂区的木兰湖，库面开阔，岛上多松，环湖有骑行道与度假村。湖边的坡地上种着橘树，环湖路有路灯。",
