  "湖北|江夏区扬子江非遗文化馆": "江夏区扬子江非遗文化馆位于武汉市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|江夏区梁子湖拾光牧场景区": "江夏区的湖畔牧场，草地临梁子湖，设帐篷、羊驼与亲子活动。牧场里的羊驼散在草地上，围栏是木的。",
  "湖北|江夏区蜜蜂探索馆": "江夏区蜜蜂探索馆位于武汉市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|江夏区龙湾半岛景区": "江夏区的湖半岛景区，三面临水，草地与林带相连，可露营垂钓。半岛的岸边多芦苇，水浅处能看见螺。",
  "湖北|江汉区江汉关博物馆": "江汉区江汉关博物馆位于武汉市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|洪山区合美术馆": "洪山区合美术馆位于武汉市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|湖北周黑鸭卤文化体验中心": "武汉的卤味主题参观区，透过玻璃看卤制与包装线，展区讲香料配比。展区的墙上写着香料配方，出口有试吃。",
  "湖北|经开区中润趣谷景区": "武汉经开区的亲子乐园，游乐设施与戏水区集中，另有萌宠园。园中的戏水池有滑梯，草坪上搭着棚。",
  "湖北|蔡甸区九真桃源景区": "蔡甸区的桃花主题园区，坡上桃林成片，春季办花节，设亲子游乐。桃林间的步道铺着碎石，路边有秋千。",
  "湖北|蔡甸区十里莲华养心谷景区": "蔡甸区的莲藕主题园区，荷塘连片，设栈道、莲品作坊与民宿。荷塘之间的栈道架在水上，塘边有凉亭。",
  "湖北|黄陂区木兰蝴蝶谷景区": "黄陂区的蝴蝶主题园区，温室放养活蝶，另有花田与昆虫展。温室里的蝴蝶落在花上，棚外有蜂箱。馆内有标本。",
  "湖北|黄陂区桃源集亲子小镇景区": "黄陂区的亲子小镇，以田园游乐、手工课堂与萌宠为主。镇上的院子做手工，草地上有滑梯。院里有菜地。",
  "湖北|广华水杉园": "广华水杉园位于潜江市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|拖船埠红色旅游景区": "潜江市的拖船埠，革命旧址与老街并存，展馆讲述当地的农运与兵事。老街的房子临河，河埠头有石阶。",
  "湖北|曹禺文化旅游区": "潜江市的曹禺文化区，故居、剧院与戏剧展陈相邻，常演《雷雨》片段。剧院里常排话剧，展柜里有手稿。院内有雕像。",
  "湖北|潜半夏中医药文化景区": "潜江的中医药主题园区，种有半夏等药材，设炮制工坊与药膳馆。药圃里的半夏种在荫棚下，作坊里晒着药材。",
  "湖北|古水河红色文化旅游区": "神农架的古水河一带，红色旧址与河谷村落并存，步道沿溪。河边的村子散在山脚，路边有纪念碑。河水很清。",
  "湖北|天生桥景区": "神农架的天生桥，溪流穿石成桥，桥下瀑布跌落，栈道沿崖绕行。桥下的水潭深，石壁上有水痕。桥边有苔藓。",
  "湖北|香溪源景区": "神农架的香溪源头，泉眼从林下涌出，溪水清浅，沿岸多古树。源头的泉水从石缝冒出，溪边长着苔藓。",
  "湖北|万寿园": "万寿园位于荆州市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|公安县北闸风景区": "公安县荆江分洪工程北闸，闸体绵长，纪念亭与展馆讲述分洪历史。闸前的江面宽，堤上种着防浪林。",
  "湖北|关帝庙": "关帝庙位于荆州市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|周老嘴湘鄂西革命根据地": "监利市周老嘴镇的老街，湘鄂西苏区机关旧址连片，青石板路两侧多为旧商铺。老街的铺板门还留着，墙上有旧标语。",
  "湖北|张居正故居": "张居正故居位于荆州市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|松滋市卸甲坪旅游区": "松滋市卸甲坪的土家族村寨，山溪与梯田相连，有温泉与吊脚楼。村里的吊脚楼临溪，坡上种着玉米。",
  "湖北|洪湖市湘鄂西苏区革命烈士陵园": "洪湖市湘鄂西苏区革命烈士陵园位于荆州市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|监利县祖师庙景区": "监利县祖师庙景区位于荆州市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|石首市南岳山森林公园": "石首市南岳山森林公园位于荆州市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|荆州九老仙都景区": "荆州城内的道教宫观，殿宇与古树相邻，旧时香火较盛。观内的院子不大，墙上嵌着碑刻。观门临着小巷。",
  "湖北|荆州关羽祠": "荆州关羽祠位于荆州市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|荆楚非物质文化遗产技能传承院": "荆州的非遗传承园区，设楚式漆器、刺绣与青铜修复工坊，可看匠人操作。院里的工坊可看漆器髹涂与刺绣针法。",
  "湖北|京山潼泉湖休闲旅游区": "京山市的湖库景区，水面多汊，环湖有果园与垂钓区。湖边的坡地上种着橘与桃，水边有钓台。湖面有白鹭。",
  "湖北|京山花台山景区": "京山市的山地景区，山道两旁多花木与茶园，山顶有观景台。山上的路两侧种着桂花，山顶有亭。山腰有茶园。",
  "湖北|沙洋县岳飞城景区": "沙洋县岳飞城景区位于荆门市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|沙洋樱花部落": "沙洋县的樱花园区，坡地种早樱晚樱，花期设栈道与市集。园中的樱花道绕水而设，树下铺着草坪。花期有集市。",
  "湖北|荆门市博物馆": "荆门市博物馆位于荆门市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
