  "湖北|大别山红军纪念园": "大别山红军纪念园位于黄冈市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|将军红四方 景区": "红安县的红色景区，展陈开国将领事迹，配有旧居与纪念广场。景区里的展板按年代排列，院中有旗杆。",
  "湖北|棠树岭风景区": "黄冈的山村景区，塘堰与梯田相连，村中有老屋与竹林。村里的塘堰边有石埠，山坡上种着茶。村里有古井。",
  "湖北|武穴七星湖度假庄园景区": "武穴七星湖度假庄园景区位于黄冈市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|武穴市仙姑山风景区": "武穴市的仙姑山，山间有庙宇与石阶古道，山顶可望长江与田野。山上的庙宇临崖，石阶两侧有栏杆。",
  "湖北|武穴市希尔寨生态农庄": "武穴市希尔寨生态农庄位于黄冈市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|武穴市横岗山景区": "武穴市横岗山，林场与寺庙并存，山脊步道起伏，春季杜鹃多。山上的林场多种松与杉，路边有防火道。",
  "湖北|武穴市龙门花海景区": "武穴市的花海园区，坡地按季种花，花间有小路与凉亭。花田旁的沟渠种着柳，路边有凉棚。田边有水渠。",
  "湖北|武穴通天河景区": "武穴市的河谷景区，河水穿村而过，岸有竹林与亲水步道。河上有一座石桥，桥下是浅滩。桥边有古树。",
  "湖北|浠水县孟家冲红色示范村景区": "浠水县孟家冲红色示范村景区位于黄冈市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|浠水县花涧谷": "浠水县的山谷花木景区，溪涧两旁种花，设木栈道与凉亭。谷中的溪边种着绣球，路边有石阶。谷口有凉亭。",
