  "湖北|浠水月湖滨水生态景区": "浠水县的城中湖，环湖绿道与广场相连，夜间有灯光。湖边的广场铺着石板，早晚有人练拳。湖中有小岛。",
  "湖北|浠水梓木星空景区": "浠水县的山地露营景区，草坪开阔，夜间观星，设帐篷与木屋。营地四周是树林，夜里风小。营地有木屋。",
