  "湖北|红安知青茶场景区": "红安县的茶场，梯状茶园连片，保留知青旧居与制茶作坊。茶场的旧屋刷着标语，屋里摆着旧农具。场里有茶园。",
  "湖北|罗田县圣人堂景区": "罗田县圣人堂村的田园，稻田与乌桕林相连，深秋红叶映着老屋。村里的田埂上种着乌桕，屋前有晒场。",
