  "湖北|罗田县天堂湖景区": "罗田县天堂湖，水库湖面绕山，岛屿零星，可乘船与环湖骑行。湖边的山势平缓，岸边有码头。湖面有薄雾。",
  "湖北|罗田县潘家湾景区": "罗田县潘家湾的梯田与古村，石阶巷道曲折，村后竹林成片。村里的石阶连着水井，屋后是竹林。村口有石桥。",
  "湖北|罗田县燕儿谷生态农庄": "罗田县燕儿谷生态农庄位于黄冈市，是3A级人文景点，保留着朴实而鲜活的地方文化记忆。景点内传统建筑、民俗物件与生活场景保存完好，展现了浓厚的乡土气息与地域特色。",
  "湖北|罗田县玖玥农谷景区": "罗田县的农旅园区，果园、花田与亲子游乐集中，设民宿。园中的果园与花田相邻，路边有栅栏。园中有池塘。",
  "湖北|罗田县胜利红色旅游区": "罗田县胜利镇的老街一带，鄂东游击队曾在此活动，旧屋与展馆并存。镇上的旧址集中在一处祠堂，祠前有广场。",
  "湖北|罗田县苍葭冲景区": "罗田县苍葭冲的古村，青砖老屋与池塘相连，村中有书院与家训墙。村里的巷子铺着青砖，墙上有家训。",
  "湖北|罗田县进士河文化旅游区": "罗田县进士河的峡谷漂流，河道在石壁间转折，落差处水花四溅。河道的起点有石阶下水，岸边长着柳。",
  "湖北|罗田柿里牧歌农旅区": "罗田县的甜柿主题园区，坡上柿树成片，设采摘与牧场体验。村里的柿树多种在田边，晒场上有切开的柿饼。",
